  ('passeios:tejo', 'passeios', 'tejo', 0, '{"id":"tejo","name":"Pôr do sol de veleiro no Tejo","place":"Lisboa","dur":"2h","price":45,"cur":"€","rating":"4,8","reviews":312,"cat":"Barco","host":"Rio Tejo Sailing","hostIni":"RT","lang":"Português e inglês","group":"Até 12 pessoas","desc":"Saída da Doca de Santo Amaro rumo à Torre de Belém, com o sol baixando atrás da ponte 25 de Abril. Volta já com as luzes da cidade acesas.","inc":["Vinho do Porto e petiscos","Skipper certificado","Cobertor pro fim de tarde"],"meet":"Doca de Santo Amaro, Alcântara","review":{"who":"Marina C.","text":"Melhor fim de tarde em Lisboa. Leve casaco, venta bastante na volta."}}'::jsonb),
  ('passeios:nata', 'passeios', 'nata', 1, '{"id":"nata","name":"Aula de pastel de nata","place":"Lisboa","dur":"3h","price":55,"cur":"€","rating":"4,9","reviews":540,"cat":"Gastronomia","host":"Cozinha da Avó Lurdes","hostIni":"AL","lang":"Português","group":"Até 8 pessoas","desc":"Massa folhada do zero, creme no ponto e forno bem quente. Você sai com uma caixa de pastéis e a receita da família.","inc":["Todos os ingredientes","Avental e receita impressa","Caixa com 6 pastéis"],"meet":"Rua da Madalena, Baixa","review":{"who":"Caio R.","text":"A Lurdes é uma figura. Os meus ficaram tortos e mesmo assim deliciosos."}}'::jsonb),
  ('passeios:lagoinha', 'passeios', 'lagoinha', 2, '{"id":"lagoinha","name":"Lagoinha do Leste com guia","place":"Florianópolis","dur":"5h","price":120,"cur":"R$","rating":"4,7","reviews":188,"cat":"Trilhas","host":"Trilhas da Ilha","hostIni":"TI","lang":"Português","group":"Até 10 pessoas","desc":"Subida pelo Pântano do Sul, parada no mirante e tarde livre numa das praias mais bonitas da ilha.","inc":["Guia credenciado","Lanche de trilha","Seguro aventura"],"meet":"Pântano do Sul, em frente à igreja","review":{"who":"João P.","text":"Trilha puxada no começo, mas a vista lá de cima compensa tudo."}}'::jsonb),
  ('passeios:fado', 'passeios', 'fado', 3, '{"id":"fado","name":"Noite de fado em Alfama","place":"Lisboa","dur":"2h30","price":38,"cur":"€","rating":"4,6","reviews":276,"cat":"Cultura","host":"Casa do Fado Vadio","hostIni":"FV","lang":"Português","group":"Até 30 pessoas","desc":"Casa pequena, luz baixa e fadistas do bairro. Inclui jantar português com entrada, prato e sobremesa.","inc":["Jantar completo","Uma taça de vinho","Lugar reservado"],"meet":"Beco do Mexias, Alfama","review":{"who":"Bia S.","text":"Arrepiou. Nada de show pra turista, é fado de verdade."}}'::jsonb),
  ('passeios:valle', 'passeios', 'valle', 4, '{"id":"valle","name":"Vale Sagrado em um dia","place":"Cusco","dur":"10h","price":280,"cur":"R$","rating":"4,8","reviews":421,"cat":"Cultura","host":"Inka Andes Tours","hostIni":"IA","lang":"Espanhol e português","group":"Até 16 pessoas","desc":"Pisac, Moray, as salinas de Maras e Ollantaytambo num só dia, com almoço buffet no caminho.","inc":["Transporte ida e volta","Guia bilíngue","Almoço buffet"],"meet":"Busca no hotel, em Cusco","review":{"who":"Rafael L.","text":"Dia longo, mas bem organizado. As salinas são surreais."}}'::jsonb),
